#[derive(Debug)]
enum Coin {
    Penny,
    Quarter(String),
}

fn main() {
    let coins = [Coin::Penny, Coin::Quarter(String::from("Alaska")), Coin::Penny];
    let mut count = 0;
    for coin in &coins {
        if let Coin::Quarter(state) = coin {
            println!("State quarter from {state}!");
        } else {
            count += 1;
        }
    }
    println!("{count} other coin(s)");
}

fn parse_point(text: &str) -> Option<(i32, i32)> {
    let Some((x, y)) = text.split_once(',') else {
        return None;
    };
    let Ok(x) = x.trim().parse() else {
        return None;
    };
    let Ok(y) = y.trim().parse() else {
        return None;
    };
    Some((x, y))
}

fn main() {
    println!("{:?}", parse_point("3, -4"));
    println!("{:?}", parse_point("3 -4"));
    println!("{:?}", parse_point("3, four"));
}

