fn describe_age(line: &str) -> String {
    if let Some((name, age)) = line.split_once(':') {
        if let Ok(age) = age.trim().parse::<u32>() {
            format!("{} is {age}", name.trim())
        } else {
            String::from("bad age")
        }
    } else {
        String::from("bad input")
    }
}

fn main() {
    for line in ["Ada: 36", "Ada 36", "Ada: old"] {
        println!("{}", describe_age(line));
    }
}

